// OpenClaw Hook：client-memory（2026-07-01 修正版）
// 問題：舊版把 workspace/CLIENT_PROFILE.md 整份塞給每一個對話者，
//       導致 A 用戶的隱私資料、以及教練內部系統資訊，被注入到 B 用戶的對話中。
// 修法：依 event.sessionKey / senderId 判斷發話者身份——
//       教練本人 → 維持整份注入（不影響教練既有體驗）
//       其他外部用戶 → 只注入「基本資訊」+ 自己那一段「## 🌟 客戶檔案」，其餘一律不給
//       抓不到身份 → 失敗關閉（只給基本資訊，不給任何客戶區塊），絕不外洩

const fs = require('fs');
const path = require('path');

const OPENCLAW_DIR = path.resolve(__dirname, '../../');
const PROFILE_PATH = path.join(OPENCLAW_DIR, 'workspace', 'CLIENT_PROFILE.md');
const COACH_ID = '6124913915';

function extractSenderId(event) {
  const sessionKey = event && event.sessionKey;
  if (typeof sessionKey === 'string') {
    const m = sessionKey.match(/telegram:direct:(\d+)/);
    if (m) return m[1];
  }
  const c = (event && event.context) || {};
  if (c.senderId) return String(c.senderId);
  if (typeof c.from === 'string') {
    const m2 = c.from.match(/(\d+)/);
    if (m2) return m2[1];
  }
  return null;
}

// 切出「基本資訊」區塊（第一個 "## 🌟 客戶檔案" 之前的內容）
function extractIntro(content) {
  const idx = content.indexOf('## 🌟 客戶檔案');
  if (idx === -1) return content.trim();
  return content.slice(0, idx).trim();
}

// 依 Telegram ID 找出屬於這個用戶自己的那一段客戶檔案
function extractOwnProfileBlock(content, senderId) {
  if (!senderId) return '';
  const parts = content.split(/(?=^## 🌟 客戶檔案：)/m);
  for (let i = 1; i < parts.length; i++) {
    if (parts[i].includes(senderId)) return parts[i].trim();
  }
  return '';
}

const handler = async (event) => {
  if (!event || typeof event !== 'object') return;
  if (event.type !== 'agent' || event.action !== 'bootstrap') return;
  if (!event.context || typeof event.context !== 'object') return;

  try {
    if (!fs.existsSync(PROFILE_PATH)) return;
    const profileContent = fs.readFileSync(PROFILE_PATH, 'utf-8');
    if (!profileContent.trim()) return;

    const senderId = extractSenderId(event);

    let scoped;
    if (senderId === COACH_ID) {
      // 教練本人：維持原本行為，整份都給
      scoped = profileContent.trim();
    } else {
      // 外部用戶：只給基本資訊 + 自己的那一段，其餘（含教練內部系統資訊、其他客戶資料）一律不給
      const intro = extractIntro(profileContent);
      const own = extractOwnProfileBlock(profileContent, senderId);
      scoped = own ? `${intro}\n\n${own}` : intro;
    }

    if (!scoped) return;

    const block = [
      '---',
      '# 📋 用戶記憶檔案（CLIENT_PROFILE）',
      '> 以下是這位用戶的背景資料，請在整個對話中牢記。',
      '',
      scoped,
      '---',
    ].join('\n');

    if (!event.context.inject) {
      event.context.inject = [];
    }
    if (Array.isArray(event.context.inject)) {
      event.context.inject.unshift({ role: 'system', content: block });
    }
  } catch (err) {
    // 靜默失敗，不影響正常對話
  }
};

module.exports = handler;
module.exports.default = handler;

