cd /Users/bymyway/.claude/projects/-Users-bymyway--openclaw && python3 -c "
import json, glob, re
from datetime import datetime, timedelta, timezone

cutoff = datetime.now(timezone.utc) - timedelta(days=32)

files = glob.glob('*.jsonl')
hits = []

patterns = [
    r'html',
    r'預覽',
    r'怎麼沒.*(出現|html|預覽)',
    r'為何沒.*(出現|html|預覽)',
    r'直接跳',
    r'不是出現',
]

for fp in files:
    try:
        with open(fp, encoding='utf-8') as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue
                try:
                    evt = json.loads(line)
                except:
                    continue
                if evt.get('type') != 'user':
                    continue
                ts = evt.get('timestamp')
                if not ts:
                    continue
                try:
                    dt = datetime.fromisoformat(ts.replace('Z','+00:00'))
                except:
                    continue
                if dt < cutoff:
                    continue
                msg = evt.get('message', {})
                content = msg.get('content')
                text = ''
                if isinstance(content, str):
                    text = content
                elif isinstance(content, list):
                    for c in content:
                        if isinstance(c, dict) and c.get('type') == 'text':
                            text += c.get('text','') + ' '
                if not text:
                    continue
                # Look for coach complaining about missing HTML preview
                if re.search(r'html|預覽', text, re.IGNORECASE) and re.search(r'沒有|怎麼|為何|不是|直接跳|一定要|每次', text):
                    hits.append((dt.isoformat(), fp, text[:200]))
    except Exception as e:
        pass

hits.sort()
print(f'Found {len(hits)} candidate messages in past 32 days')
print()
for dt, fp, text in hits:
    print(f'--- {dt} [{fp[:8]}] ---')
    print(text)
    print()
"

